-- UNDO for step 88 (0342). Only if step 88 misbehaves (for example an organization admin can no longer see a client they should, or training-partner matching stops listing people). Puts the five functions back exactly as they were and opens the two coach-count functions to signed-in users again.
-- WHAT YOU SHOULD SEE: "Success. No rows returned."   Then tell Spot, and do not run the step again until Spot says why it failed.
begin;
create or replace function public.training_partners_share_org(a uuid, b uuid) returns boolean language sql stable security definer set search_path to 'public' as $function$ select exists (select 1 from public.group_memberships gm_a join public.groups g_a on g_a.id = gm_a.group_id join public.group_memberships gm_b on gm_b.profile_id = b join public.groups g_b on g_b.id = gm_b.group_id where gm_a.profile_id = a and g_a.organization_id is not null and g_b.organization_id = g_a.organization_id); $function$;
create or replace function public.training_partners_mutually_blocked(a uuid, b uuid) returns boolean language sql stable security definer set search_path to 'public' as $function$ select exists (select 1 from public.training_partner_blocks where (blocker_id = a and blocked_id = b) or (blocker_id = b and blocked_id = a)); $function$;
create or replace function public.is_training_client_of_group(_group_id uuid, _athlete_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path to 'public' as $function$ select exists (select 1 from public.group_memberships where group_id = _group_id and profile_id = _athlete_id and role = 'athlete' and membership_type = 'training'); $function$;
create or replace function public.is_client_private_from_org(_group_id uuid, _athlete_id uuid) returns boolean language sql stable security definer set search_path to 'public' as $function$ select coalesce((select private_from_org from public.group_memberships where group_id = _group_id and profile_id = _athlete_id), false); $function$;
create or replace function public.is_wearable_subject_private_from_org(_profile_id uuid) returns boolean language sql stable security definer set search_path to 'public' as $function$ select exists (select 1 from public.group_memberships where profile_id = _profile_id and private_from_org = true); $function$;
grant execute on function public.coach_ai_multiplier(uuid) to public, anon, authenticated;
grant execute on function public.coach_client_steps(uuid) to public, anon, authenticated;
commit;
